#include <iostream>
#include <string>
using namespace std;

class Cat {
protected:
    string name;
    int fish;
public:
    Cat(string n, int f) : name(n), fish(f) {}
    virtual void speak() const {
        cout << name << "：" << endl;
    }
};

class OrangeCat : public Cat {
public:
    OrangeCat(string n, int f) : Cat(n, f) {}
    void speak() const override {
        cout << name << "：我们是学生甲，处理了 " << fish << " 条，！" << endl;
    }
};

class TabbyCat : public Cat {
public:
    TabbyCat(string n, int f) : Cat(n, f) {}
    void speak() const override {
        cout << name << "：我们是学生乙，处理了 " << fish << " 条，呜" << endl;
    }
};

class BlackCat : public Cat {
public:
    BlackCat(string n, int f) : Cat(n, f) {}
    void speak() const override {
        cout << name << "：我们是学生丁，处理了 " << fish << " 条，嗷" << endl;
    }
};

int main() {
    int a = 0;
    int b = 0;
    int c = 0;
    cin >> a >> b >> c;

    OrangeCat o("张三", a);
    TabbyCat t("李四", b);
    BlackCat k("煤球", c);

    Cat* cats[3];
    cats[0] = &o;
    cats[1] = &t;
    cats[2] = &k;

    for (int i = 0; i < 3; i++) {
        cats[i]->speak();
    }
    return 0;
}

